import { useState, useMemo } from 'react';
import {
  Card,
  Stack,
  TextField,
  HelperText,
  Select,
  SelectOption,
  Switch,
  Button,
  Alert,
  IconButton,
} from '@jinx-ui/react';

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

type Role = 'member' | 'admin' | 'viewer';

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<Role>('member');
  const [notify, setNotify] = useState(true);
  const [touched, setTouched] = useState(false);
  const [success, setSuccess] = useState(false);

  const isEmailValid = useMemo(() => EMAIL_REGEX.test(email.trim()), [email]);
  const showError = touched && !isEmailValid && email.length > 0;
  const showEmptyError = touched && email.length === 0;

  const canSubmit = isEmailValid && email.length > 0;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setTouched(true);
    if (!canSubmit) return;
    setSuccess(true);
    setEmail('');
    setRole('member');
    setNotify(true);
    setTouched(false);
  };

  return (
    <Stack direction="column" gap="md" className="jx-max-w-md">
      {success && (
        <Alert
          variant="success"
          title="Приглашение отправлено"
          action={
            <IconButton
              icon="x"
              aria-label="Закрыть сообщение"
              variant="ghost"
              onClick={() => setSuccess(false)}
            />
          }
        >
          Участник получит письмо со ссылкой для присоединения к команде.
        </Alert>
      )}

      <Card padding="lg">
        <form onSubmit={handleSubmit} noValidate>
          <Stack direction="column" gap="md">
            <Stack direction="column" gap="xs">
              <TextField
                label="Email"
                type="email"
                placeholder="name@company.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                onBlur={() => setTouched(true)}
                invalid={showError || showEmptyError}
                required
              />
              {showEmptyError && (
                <HelperText variant="error">Укажите email участника</HelperText>
              )}
              {showError && (
                <HelperText variant="error">
                  Похоже, это не email. Проверьте адрес и попробуйте снова.
                </HelperText>
              )}
              {!showError && !showEmptyError && (
                <HelperText>Мы отправим приглашение на этот адрес</HelperText>
              )}
            </Stack>

            <Select
              label="Роль"
              value={role}
              onValueChange={(value) => setRole(value as Role)}
            >
              <SelectOption value="member">Участник</SelectOption>
              <SelectOption value="admin">Администратор</SelectOption>
              <SelectOption value="viewer">Наблюдатель</SelectOption>
            </Select>

            <Switch
              checked={notify}
              onCheckedChange={setNotify}
              label="Отправить уведомление по email"
            />

            <Button type="submit" variant="primary" disabled={!canSubmit}>
              Отправить приглашение
            </Button>
          </Stack>
        </form>
      </Card>
    </Stack>
  );
}

